import { by, device, element, expect, waitFor } from 'detox';

describe('checkout', () => {
  beforeEach(async () => {
    await device.launchApp({ newInstance: true, delete: true });
  });

  it('places an order from the cart', async () => {
    await element(by.id('add-to-cart-0')).tap();
    await element(by.id('cart-tab')).tap();
    await element(by.id('checkout-button')).tap();
    await waitFor(element(by.id('order-confirmation')))
      .toBeVisible()
      .withTimeout(10000);
    expect(element(by.id('order-number'))).toBeVisible();
  });
});

import { by, device, element, expect } from 'detox';
import { resetCart, seedUser } from './helpers/api';

const EMAIL = 'e2e-shopper@acme.test';

describe('cart', () => {
  beforeEach(async () => {
    await seedUser(EMAIL);
    await resetCart(EMAIL);
    await device.launchApp({ newInstance: true, delete: true, launchArgs: { e2eEmail: EMAIL } });
  });

  it('shows the item count after adding two products', async () => {
    await element(by.id('add-to-cart-0')).tap();
    await element(by.id('add-to-cart-1')).tap();
    await expect(element(by.id('cart-badge'))).toHaveText('2');
  });
});
